using Microsoft.EntityFrameworkCore;
using System.Text.Json;
using System.Collections.Generic;
using System.Linq;
var results=new List<object>();
async Task Check(string name,Func<Task> test){try{await test();results.Add(new{name,passed=true,detail=""});}catch(Exception e){results.Add(new{name,passed=false,detail=e.Message});}}
void Eq<T>(T expected,T actual){if(!EqualityComparer<T>.Default.Equals(expected,actual))throw new Exception($"Expected {expected}; got {actual}");}
async Task ThrowsAsync<T>(Func<Task> f) where T:Exception{try{await f();}catch(T){return;}throw new Exception($"Expected {typeof(T).Name}");}
await Check("Успех",async()=>{await using var cn=new Microsoft.Data.Sqlite.SqliteConnection("Data Source=:memory:");await cn.OpenAsync();var options=new DbContextOptionsBuilder<TxDb>().UseSqlite(cn).Options;await using var db=new TxDb(options);await db.Database.EnsureCreatedAsync();db.Accounts.AddRange(new TxAccount{Id=1,Balance=100},new TxAccount{Id=2,Balance=20});await db.SaveChangesAsync();db.ChangeTracker.Clear();int calls=0;await Kata.TransferAsync(db,1,2,30,()=>{calls++;return Task.CompletedTask;},default);Eq(1,calls);await using var v=new TxDb(options);Eq(70,await v.Accounts.Where(x=>x.Id==1).Select(x=>x.Balance).SingleAsync());Eq(50,await v.Accounts.Where(x=>x.Id==2).Select(x=>x.Balance).SingleAsync());var a=await v.Audits.SingleAsync();Eq(1,a.FromId);Eq(2,a.ToId);Eq(30,a.Amount);});
await Check("Rollback после debit",async()=>{await using var cn=new Microsoft.Data.Sqlite.SqliteConnection("Data Source=:memory:");await cn.OpenAsync();var options=new DbContextOptionsBuilder<TxDb>().UseSqlite(cn).Options;await using var db=new TxDb(options);await db.Database.EnsureCreatedAsync();db.Accounts.AddRange(new TxAccount{Id=1,Balance=100},new TxAccount{Id=2,Balance=20});await db.SaveChangesAsync();db.ChangeTracker.Clear();var expected=new ApplicationException("failure hook");try{await Kata.TransferAsync(db,1,2,30,async()=>{Eq(70,await db.Accounts.AsNoTracking().Where(x=>x.Id==1).Select(x=>x.Balance).SingleAsync());Eq(20,await db.Accounts.AsNoTracking().Where(x=>x.Id==2).Select(x=>x.Balance).SingleAsync());Eq(0,await db.Audits.CountAsync());throw expected;},default);throw new Exception("Failure swallowed");}catch(ApplicationException ex){Eq(true,ReferenceEquals(expected,ex));}await using var verify=new TxDb(options);Eq(100,await verify.Accounts.Where(x=>x.Id==1).Select(x=>x.Balance).SingleAsync());Eq(20,await verify.Accounts.Where(x=>x.Id==2).Select(x=>x.Balance).SingleAsync());Eq(0,await verify.Audits.CountAsync());});
await Check("Нет средств",async()=>{await using var cn=new Microsoft.Data.Sqlite.SqliteConnection("Data Source=:memory:");await cn.OpenAsync();var options=new DbContextOptionsBuilder<TxDb>().UseSqlite(cn).Options;await using var db=new TxDb(options);await db.Database.EnsureCreatedAsync();db.Accounts.AddRange(new TxAccount{Id=1,Balance=100},new TxAccount{Id=2,Balance=20});await db.SaveChangesAsync();db.ChangeTracker.Clear();int calls=0;await ThrowsAsync<InvalidOperationException>(()=>Kata.TransferAsync(db,1,2,101,()=>{calls++;return Task.CompletedTask;},default));Eq(0,calls);await using var verify=new TxDb(options);Eq(100,await verify.Accounts.Where(x=>x.Id==1).Select(x=>x.Balance).SingleAsync());Eq(20,await verify.Accounts.Where(x=>x.Id==2).Select(x=>x.Balance).SingleAsync());Eq(0,await verify.Audits.CountAsync());});
await Check("Нет получателя",async()=>{await using var cn=new Microsoft.Data.Sqlite.SqliteConnection("Data Source=:memory:");await cn.OpenAsync();var options=new DbContextOptionsBuilder<TxDb>().UseSqlite(cn).Options;await using var db=new TxDb(options);await db.Database.EnsureCreatedAsync();db.Accounts.AddRange(new TxAccount{Id=1,Balance=100},new TxAccount{Id=2,Balance=20});await db.SaveChangesAsync();db.ChangeTracker.Clear();await ThrowsAsync<InvalidOperationException>(()=>Kata.TransferAsync(db,1,99,30,()=>Task.CompletedTask,default));await using var verify=new TxDb(options);Eq(100,await verify.Accounts.Where(x=>x.Id==1).Select(x=>x.Balance).SingleAsync());Eq(20,await verify.Accounts.Where(x=>x.Id==2).Select(x=>x.Balance).SingleAsync());Eq(0,await verify.Audits.CountAsync());});
await Check("Отмена",async()=>{await using var cn=new Microsoft.Data.Sqlite.SqliteConnection("Data Source=:memory:");await cn.OpenAsync();var options=new DbContextOptionsBuilder<TxDb>().UseSqlite(cn).Options;await using var db=new TxDb(options);await db.Database.EnsureCreatedAsync();db.Accounts.AddRange(new TxAccount{Id=1,Balance=100},new TxAccount{Id=2,Balance=20});await db.SaveChangesAsync();db.ChangeTracker.Clear();using var cts=new CancellationTokenSource();cts.Cancel();int calls=0;await ThrowsAsync<OperationCanceledException>(()=>Kata.TransferAsync(db,1,2,30,()=>{calls++;return Task.CompletedTask;},cts.Token));Eq(0,calls);await using var verify=new TxDb(options);Eq(100,await verify.Accounts.Where(x=>x.Id==1).Select(x=>x.Balance).SingleAsync());Eq(20,await verify.Accounts.Where(x=>x.Id==2).Select(x=>x.Balance).SingleAsync());Eq(0,await verify.Audits.CountAsync());});
await Check("SaveChanges отказ",async()=>{await using var cn=new Microsoft.Data.Sqlite.SqliteConnection("Data Source=:memory:");await cn.OpenAsync();var options=new DbContextOptionsBuilder<TxDb>().UseSqlite(cn).Options;await using var db=new TxDb(options);await db.Database.EnsureCreatedAsync();db.Accounts.AddRange(new TxAccount{Id=1,Balance=100},new TxAccount{Id=2,Balance=20});await db.SaveChangesAsync();db.ChangeTracker.Clear();await db.Database.ExecuteSqlRawAsync("CREATE TRIGGER reject_audit BEFORE INSERT ON Audits BEGIN SELECT RAISE(ABORT,'audit disabled'); END;");await ThrowsAsync<DbUpdateException>(()=>Kata.TransferAsync(db,1,2,30,()=>Task.CompletedTask,default));await using var verify=new TxDb(options);Eq(100,await verify.Accounts.Where(x=>x.Id==1).Select(x=>x.Balance).SingleAsync());Eq(20,await verify.Accounts.Where(x=>x.Id==2).Select(x=>x.Balance).SingleAsync());Eq(0,await verify.Audits.CountAsync());});
await Check("Валидация",async()=>{await using var cn=new Microsoft.Data.Sqlite.SqliteConnection("Data Source=:memory:");await cn.OpenAsync();var options=new DbContextOptionsBuilder<TxDb>().UseSqlite(cn).Options;await using var db=new TxDb(options);await db.Database.EnsureCreatedAsync();db.Accounts.AddRange(new TxAccount{Id=1,Balance=100},new TxAccount{Id=2,Balance=20});await db.SaveChangesAsync();db.ChangeTracker.Clear();await ThrowsAsync<ArgumentNullException>(()=>Kata.TransferAsync(null!,1,2,1,()=>Task.CompletedTask,default));await ThrowsAsync<ArgumentNullException>(()=>Kata.TransferAsync(db,1,2,1,null!,default));await ThrowsAsync<ArgumentOutOfRangeException>(()=>Kata.TransferAsync(db,1,2,0,()=>Task.CompletedTask,default));await ThrowsAsync<ArgumentException>(()=>Kata.TransferAsync(db,1,1,1,()=>Task.CompletedTask,default));await using var verify=new TxDb(options);Eq(100,await verify.Accounts.Where(x=>x.Id==1).Select(x=>x.Balance).SingleAsync());Eq(20,await verify.Accounts.Where(x=>x.Id==2).Select(x=>x.Balance).SingleAsync());Eq(0,await verify.Audits.CountAsync());});
Console.WriteLine(JsonSerializer.Serialize(results));
